import type { Metadata } from "next";
import { Barlow, Barlow_Condensed } from "next/font/google";

import { content } from "@/lib/content/content";
import { getMenu } from "@/lib/content/menu";
import { getFooter } from "@/lib/content/footer";
import { getSiteText } from "@/lib/content/site-text";
import type { Section } from "@/lib/content/sections";
import { Cinematic, type Scene, type Slide } from "./Cinematic";

/*
 * PREVIEW ONLY: a cinematic, full-screen take on the homepage, in the manner
 * of spacex.com. Not linked from anywhere and not indexed. It reads the same
 * homepage content the admin edits, so the words and photographs are real.
 * Delete this folder to remove it.
 */

export const metadata: Metadata = {
  title: "Cinematic homepage (preview)",
  robots: { index: false, follow: false },
};

const display = Barlow_Condensed({ subsets: ["latin"], weight: ["500", "600"], variable: "--font-cine-display", display: "swap" });
const text = Barlow({ subsets: ["latin"], weight: ["400", "500"], variable: "--font-cine-text", display: "swap" });

/** First sentence only: a full-screen panel carries one thought. */
const firstSentence = (body: string) => {
  const match = /^(.+?[.!?])(\s|$)/.exec(body.trim());
  return match ? match[1] : body;
};

/** Group the homepage's sections into scenes: related slides share a screen. */
function toScenes(sections: readonly Section[]): Scene[] {
  const scenes: Scene[] = [];
  const shop: { id: string; title: string; kicker: string; href: string; image?: string }[] = [];
  let statement: { quote: string; body: string } | undefined;
  let closing: Scene | undefined;
  let edits: Scene | undefined;

  for (const section of sections) {
    switch (section.type) {
      case "heroCarousel":
        scenes.push({
          kind: "slides",
          id: section.id,
          transition: "fade",
          isPageTitle: true,
          slides: section.slides.map(
            (slide): Slide => ({
              id: slide.id,
              kicker: slide.eyebrow,
              title: slide.title,
              body: slide.body,
              cta: { label: slide.ctaLabel, href: slide.ctaHref },
              image: slide.art.desktop.src,
              mobileImage: slide.art.mobile.src,
              align: slide.align === "right" ? "right" : "left",
            }),
          ),
        });
        break;
      case "brandStatement":
        statement = { quote: section.quote, body: section.body };
        break;
      case "collectionTriptych":
        scenes.push({
          kind: "story",
          id: section.id,
          statement,
          photos: section.art.map((art, i) => ({
            image: art.desktop.src,
            href: section.artHrefs?.[i] ?? section.ctaHref,
          })),
          title: section.title,
          body: section.body,
          cta: { label: section.ctaLabel, href: section.ctaHref },
          secondary: { label: "Shop the pieces", href: section.ctaHref },
        });
        break;
      case "tileRow":
        edits = {
          kind: "edits",
          id: section.id,
          items: section.items.map((item) => ({
            label: item.label.charAt(0) + item.label.slice(1).toLowerCase(),
            href: item.href,
            image: item.art.desktop.src,
          })),
        };
        break;
      case "richText":
        if (section.heading && section.paragraphs.length > 0) {
          closing = { kind: "words", id: section.id, title: section.heading, body: section.paragraphs.join(" ") };
        }
        break;
      case "videoBand":
        scenes.push({
          kind: "film",
          id: section.id,
          kicker: "On the loom",
          title: section.title,
          body: section.body,
          cta: { label: section.ctaLabel, href: section.ctaHref },
          image: section.art.desktop.src,
          video: section.videoSrc,
          facts: [
            { figure: "6–26", label: "Weeks on the loom" },
            { figure: "By hand", label: "Every thread" },
            { figure: "Varanasi", label: "Where it is woven" },
          ],
        });
        break;
      case "categorySplit":
        for (const item of section.items) {
          const name = item.label.charAt(0) + item.label.slice(1).toLowerCase();
          shop.push({ id: item.label, title: name, kicker: "Shop", href: item.href, image: item.art.desktop.src });
        }
        break;
      case "editorialSlideshow":
        for (const slide of section.slides) {
          shop.push({
            id: slide.id,
            title: slide.title === "Womenswear" ? "All pieces" : slide.title,
            kicker: slide.title === "Womenswear" ? "The collection" : "Shop",
            href: slide.ctaHref,
            image: slide.art.desktop.src,
          });
        }
        break;
      case "campaignSlideshow":
        scenes.push({
          kind: "slides",
          id: section.id,
          transition: "wipe",
          slides: section.slides.map(
            (slide): Slide => ({
              id: slide.id,
              kicker: "Campaign",
              title: slide.title,
              body: firstSentence(slide.body),
              cta: { label: slide.ctaLabel, href: slide.ctaHref },
              secondary: { label: "Shop the pieces", href: "/collections/all" },
              image: slide.art.desktop.src,
              align: "left",
            }),
          ),
        });
        break;
      case "storesSlideshow":
        scenes.push({
          kind: "slides",
          id: section.id,
          transition: "fade",
          slides: section.slides.map(
            (slide): Slide => ({
              id: slide.id,
              kicker: "Visit, by appointment",
              title: slide.ctaLabel.replace(/\s*Store$/i, ""),
              body: slide.body,
              cta: { label: "Book a visit", href: slide.ctaHref },
              image: slide.art.desktop.src,
              align: "left",
            }),
          ),
        });
        break;
      default:
        break;
    }
  }

  // The four curated edits follow the shop strips (placed below, once the
  // strips are in), so both shopping scenes sit together.
  // The closing words sit just before the visit scene.
  if (closing) {
    const visit = scenes.findIndex((scene) => scene.kind === "slides" && scene.id.startsWith("stores"));
    scenes.splice(visit >= 0 ? visit : scenes.length, 0, closing);
  }
  // The shop strips sit straight after the loom film (or after the hero if there is no film).
  if (shop.length > 0) {
    const film = scenes.findIndex((scene) => scene.kind === "film");
    scenes.splice(film >= 0 ? film + 1 : 1, 0, { kind: "shop", id: "shop", items: shop });
  }
  if (edits) {
    const shopAt = scenes.findIndex((scene) => scene.kind === "shop");
    scenes.splice(shopAt >= 0 ? shopAt + 1 : scenes.length, 0, edits);
  }
  return scenes;
}

export default async function CinematicPreview() {
  const [sections, menu, footer, siteText] = await Promise.all([content.getHomepageSections(), getMenu(), getFooter(), getSiteText()]);
  return (
    <div className={`${display.variable} ${text.variable}`}>
      <Cinematic
        scenes={toScenes(sections)}
        menu={menu}
        footer={{
          newsletterHeading: footer.newsletterHeading,
          newsletterText: footer.newsletterText,
          newsletterButton: footer.newsletterButton,
          email: siteText["contact.email"],
          phone: siteText["contact.phone"],
          whatsappLabel: "Chat on WhatsApp",
          hours: siteText["contact.hours"].split("\n").map((line) => line.trim()).filter(Boolean),
          legalName: footer.copyrightName,
        }}
      />
    </div>
  );
}
